		trigger = {
			fromfrom = {
				is_ship_class = shipclass_military
				root = {
					country_uses_bio_ships = yes
				}
			}
		}
		picture = GFX_evt_bio_ships_orbiting
	}
	picture = {
		trigger = {
			fromfrom = {
				is_ship_class = shipclass_military_station
				root = {
					country_uses_bio_ships = yes
				}
			}
		}
		picture = GFX_evt_bioship_hangar
	}
	location = ROOT

	is_triggered_only = yes

	trigger = {
		is_country_type = default
		any_owned_leader = {
			leader_class = commander
		}
		NOT = {
			has_country_flag = recent_promising_officer
		}
		FROMFROM = { #Civilian Ships should not generate officers
			OR = {
				is_ship_class = shipclass_military_station
				is_ship_class = shipclass_military
			}
		}
	}

	immediate = {
		set_timed_country_flag = {
			flag = recent_promising_officer
			days = 720
		}
		FROMFROM = {
			solar_system = { save_event_target_as = system }
			random_controlled_ship = {
				save_event_target_as = ship
			}
		}
		random_list = {
			25 = {
				create_leader = {
					class = commander
					species = owner_main_species
					name = random
					skill = 2
					traits = {
						1 = leader_trait_gale_speed
						2 = leader_trait_aggressive
						0 = leader_trait_eager
					}
				}
				last_created_leader = { save_event_target_as = officer }
			}
			25 = {
				create_leader = {
					class = commander
					species = owner_main_species
					name = random
					skill = 2
					traits = {
						1 = leader_trait_aggressive
						2 = leader_trait_engineer
						0 = leader_trait_eager
					}
				}
				last_created_leader = { save_event_target_as = officer }
			}
			25 = {
				create_leader = {
					class = commander
					species = owner_main_species
					name = random
					skill = 2
					traits = {
						1 = leader_trait_fleet_logistician
						2 = leader_trait_cautious
						0 = leader_trait_eager
					}
				}
				last_created_leader = { save_event_target_as = officer }
			}
			25 = {
				create_leader = {
					class = commander
					species = owner_main_species
					name = random
					skill = 2
					traits = {
						1 = leader_trait_scout
						2 = leader_trait_trickster
						0 = leader_trait_eager
					}
				}
				last_created_leader = { save_event_target_as = officer }
			}
		}
	}

	option = {
		name = GOOD
		custom_tooltip = new_admiral
	}
}

